<?php
require_once __DIR__.'/../config/bootstrap.php'; require_role('administrador');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$uid=(int)($_POST['unidad_id']??0);$teacher=(int)($_POST['docente_id']??0);$day=(int)($_POST['dia_semana']??0);$start=$_POST['hora_inicio']??'';$end=$_POST['hora_fin']??'';$room=trim($_POST['aula']??'');$career=(int)($_POST['carrera_id']??0);$mod=(int)($_POST['modulo_num']??0);$cycle=(int)($_POST['ciclo_num']??0);
if($uid&&$teacher&&$day>=1&&$day<=7&&$start<$end&&$career&&$mod>=1&&$mod<=3&&$cycle>=1&&$cycle<=2){
 $s=$pdo->prepare("SELECT id FROM horarios WHERE dia_semana=? AND ((docente_id=? AND hora_inicio < ? AND hora_fin > ?) OR (aula=? AND hora_inicio < ? AND hora_fin > ?) OR (carrera_id=? AND modulo_num=? AND ciclo_num=? AND hora_inicio < ? AND hora_fin > ?))");
 $s->execute([$day,$teacher,$end,$start,$room,$end,$start,$career,$mod,$cycle,$end,$start]);
 if($s->fetch()) flash('error','Conflicto detectado: el docente, aula o grupo ya tiene un horario que se cruza.');
 else{$s=$pdo->prepare('INSERT INTO horarios(unidad_id,docente_id,carrera_id,modulo_num,ciclo_num,dia_semana,hora_inicio,hora_fin,aula) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$uid,$teacher,$career,$mod,$cycle,$day,$start,$end,$room]);audit($pdo,(int)current_user()['id'],'crear_horario',"Unidad {$uid}; docente {$teacher}");flash('success','Horario guardado.');}
}else flash('error','Completa los datos del horario correctamente.');redirect('horarios.php');}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];http_response_code(405);exit('Para eliminar horarios utiliza una petición POST desde una versión protegida del panel.');}
$units=$pdo->query('SELECT id,nombre FROM unidades_didacticas ORDER BY nombre')->fetchAll();$teachers=$pdo->query("SELECT id,nombres,apellidos FROM usuarios WHERE rol='docente' AND estado='activo' ORDER BY apellidos")->fetchAll();$careers=$pdo->query('SELECT * FROM carreras')->fetchAll();$rows=$pdo->query('SELECT h.*,u.nombre unidad,us.nombres,us.apellidos,c.nombre carrera FROM horarios h JOIN unidades_didacticas u ON u.id=h.unidad_id JOIN usuarios us ON us.id=h.docente_id JOIN carreras c ON c.id=h.carrera_id ORDER BY h.dia_semana,h.hora_inicio')->fetchAll();
$pageTitle='Horarios';$assetPrefix='../';require __DIR__.'/../includes/header.php';?>
<div class="dashboard-head"><div><div class="eyebrow">ORGANIZACIÓN</div><h1>Gestión de horarios</h1></div><a class="btn secondary" href="index.php">Volver</a></div>
<section class="panel"><h2>Crear horario</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><div class="field"><label>Unidad didáctica</label><select name="unidad_id" required><?php foreach($units as $u):?><option value="<?= (int)$u['id']?>"><?= h($u['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label>Docente</label><select name="docente_id" required><?php foreach($teachers as $t):?><option value="<?= (int)$t['id']?>"><?= h($t['apellidos'].', '.$t['nombres'])?></option><?php endforeach;?></select></div><div class="field"><label>Carrera</label><select name="carrera_id" required><?php foreach($careers as $c):?><option value="<?= (int)$c['id']?>"><?= h($c['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label>Módulo</label><select name="modulo_num"><?php for($i=1;$i<=3;$i++):?><option><?= $i?></option><?php endfor;?></select></div><div class="field"><label>Ciclo</label><select name="ciclo_num"><?php for($i=1;$i<=2;$i++):?><option><?= $i?></option><?php endfor;?></select></div><div class="field"><label>Día</label><select name="dia_semana"><?php foreach([1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'] as $k=>$v):?><option value="<?= $k?>"><?= $v?></option><?php endforeach;?></select></div><div class="field"><label>Hora de inicio</label><input type="time" name="hora_inicio" required></div><div class="field"><label>Hora de fin</label><input type="time" name="hora_fin" required></div><div class="field"><label>Aula</label><input name="aula" maxlength="50" required></div><div class="field full"><button class="btn primary">Guardar horario</button></div></form></section>
<section class="panel"><h2>Horarios registrados</h2><div class="table-wrap"><table><thead><tr><th>Día</th><th>Hora</th><th>Unidad</th><th>Docente</th><th>Grupo</th><th>Aula</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= [1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'][$r['dia_semana']]?></td><td><?= h(substr($r['hora_inicio'],0,5).'–'.substr($r['hora_fin'],0,5))?></td><td><?= h($r['unidad'])?></td><td><?= h($r['nombres'].' '.$r['apellidos'])?></td><td><?= h($r['carrera'].' · M'.$r['modulo_num'].' C'.$r['ciclo_num'])?></td><td><?= h($r['aula'])?></td></tr><?php endforeach;?></tbody></table></div></section>
